from collections import deque, Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    frames = []
    frame_cells = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            r0, r1 = min(y for y,x in comp), max(y for y,x in comp)
            c0, c1 = min(x for y,x in comp), max(x for y,x in comp)
            if r1-r0 >= 2 and c1-c0 >= 2:
                perimeter = {(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)
                             if y in (r0,r1) or x in (c0,c1)}
                if set(comp) == perimeter:
                    frames.append((r0,r1,c0,c1,color))
                    frame_cells.update(perimeter)
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if grid[r][c] and (r,c) not in frame_cells)
    out = [[0 for _ in range(w)] for _ in range(h)]
    for r0,r1,c0,c1,border in frames:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if r in (r0,r1) or c in (c0,c1):
                    out[r][c] = border
    for r0,r1,c0,c1,border in frames:
        ir0, ir1, ic0, ic1 = r0+1,r1-1,c0+1,c1-1
        target_count = sum(1 for r in range(ir0,ir1+1) for c in range(ic0,ic1+1)
                           if (r-ir0+c-ic0)%2 == 0)
        fill = min(counts, key=lambda color: abs(counts[color] - target_count)) if counts else None
        if fill is not None:
            for r in range(ir0,ir1+1):
                for c in range(ic0,ic1+1):
                    if (r-ir0+c-ic0)%2 == 0:
                        out[r][c] = fill
    return out
